import { memo, useState } from "react";
import { Brain, ChevronRight, Wrench } from "../../assets/icons";
import { OrbLoader } from "../../components/OrbLoader";
import { useI18n } from "../../components/useI18n";
import { AttachmentChip } from "../../components/AttachmentChip";
import { ToolGlyph, humanizeToolName } from "../../components/toolMeta";
import { HermesAvatar, AvatarSpacer } from "./MessageRow";
import type { AgentAvatarInfo } from "./MessageRow";
import type {
  Attachment,
  ReasoningMessage,
  ToolCallMessage,
  ToolResultMessage,
} from "./types";

/* ── Reasoning ────────────────────────────────────────────────────────── */

export const ReasoningRow = memo(function ReasoningRow({
  msg,
  active = false,
  showAvatar = true,
  agent,
}: {
  msg: ReasoningMessage;
  /** True only while this turn's reasoning is still streaming. Controls the
   *  present-vs-past label ("Thinking…" vs "Thought"). */
  active?: boolean;
  /** False on continuation rows of a turn — render a spacer instead of an
   *  avatar so one turn shows a single avatar. */
  showAvatar?: boolean;
  /** Appearance of the chatting agent, shown once the avatar goes idle. */
  agent?: AgentAvatarInfo;
}): React.JSX.Element {
  const { t } = useI18n();
  const [open, setOpen] = useState(false);
  return (
    <div
      className={`chat-message chat-message-agent chat-message-history${
        showAvatar ? "" : " chat-message--grouped"
      }`}
    >
      {showAvatar ? (
        <HermesAvatar active={active} agent={agent} />
      ) : (
        <AvatarSpacer />
      )}
      <div
        className={`chat-reasoning-group${
          active ? " chat-reasoning-group--active" : ""
        }`}
      >
        <button
          type="button"
          className="chat-reasoning-group-summary"
          aria-expanded={open}
          onClick={() => setOpen((o) => !o)}
        >
          {active ? (
            <OrbLoader
              state="solving"
              size={20}
              aria-label="thinking-loading"
              className="chat-reasoning-group-spinner"
            />
          ) : (
            <Brain size={13} className="chat-reasoning-group-icon" />
          )}
          <span className="chat-reasoning-group-title">
            {active ? t("chat.thinking") : t("chat.thought")}
          </span>
          <ChevronRight
            size={14}
            className={`chat-reasoning-group-chevron${
              open ? " chat-reasoning-group-chevron--open" : ""
            }`}
          />
        </button>
        <div
          className={`chat-tool-collapse${
            open ? " chat-tool-collapse--open" : ""
          }`}
        >
          <div className="chat-tool-collapse-inner">
            <pre className="chat-history-pre">{msg.text}</pre>
          </div>
        </div>
      </div>
    </div>
  );
});

/* ── Tool activity (grouped) ──────────────────────────────────────────────
 *
 * A contiguous run of tool calls/results collapses into a single block —
 * the way ChatGPT and Claude fold a burst of tool use into one line. The
 * collapsed summary shows the most recent step (plus a total count); the
 * whole run expands smoothly to reveal every step, and each step in turn
 * expands to its full arguments/output. This keeps a 100-call turn from
 * exploding into 100 stacked bubbles.
 */

type ToolItem = ToolCallMessage | ToolResultMessage;

function summariseArgs(args: string): string {
  // Single-line snippet for the collapsed header — show the first ~80
  // chars, collapse whitespace so multi-line JSON doesn't break layout.
  const flat = args.replace(/\s+/g, " ").trim();
  if (flat.length <= 80) return flat;
  return flat.slice(0, 77) + "…";
}

function countLines(text: string): number {
  if (!text) return 0;
  return text.split("\n").length;
}

function isToolCall(msg: ToolItem): msg is ToolCallMessage {
  return msg.kind === "tool_call";
}

export function toolActivityGroupTitle(items: ToolItem[]): string {
  const toolCallCount = items.filter(isToolCall).length;
  if (toolCallCount > 1) return `${toolCallCount} tools called`;
  const name = items[items.length - 1]?.name;
  return name ? humanizeToolName(name) : "Tool";
}

/** The single tool name in a group, or null when the group spans several. */
function singleToolName(items: ToolItem[]): string | null {
  if (items.filter(isToolCall).length > 1) return null;
  return items[items.length - 1]?.name ?? null;
}

export function orderToolActivityItems(items: ToolItem[]): ToolItem[] {
  const callIds = new Set(
    items
      .filter(isToolCall)
      .map((item) => item.callId)
      .filter(Boolean),
  );
  const resultsByCallId = new Map<string, ToolResultMessage[]>();
  for (const item of items) {
    if (isToolCall(item) || !item.callId) continue;
    const bucket = resultsByCallId.get(item.callId) ?? [];
    bucket.push(item);
    resultsByCallId.set(item.callId, bucket);
  }

  const emittedResults = new Set<ToolResultMessage>();
  const ordered: ToolItem[] = [];
  for (const item of items) {
    if (isToolCall(item)) {
      ordered.push(item);
      for (const result of resultsByCallId.get(item.callId) ?? []) {
        ordered.push(result);
        emittedResults.add(result);
      }
      continue;
    }

    if (emittedResults.has(item)) continue;
    if (item.callId && callIds.has(item.callId)) continue;
    ordered.push(item);
    emittedResults.add(item);
  }

  return ordered;
}

function resultMeta(msg: ToolResultMessage): string {
  const lines = countLines(msg.content);
  const base = `${lines} ${lines === 1 ? "line" : "lines"}`;
  const n = msg.attachments?.length ?? 0;
  return n > 0 ? `${base} · ${n} attachment${n === 1 ? "" : "s"}` : base;
}

function itemDetail(msg: ToolItem): string {
  return isToolCall(msg) ? summariseArgs(msg.args) : resultMeta(msg);
}

const ToolActivityItem = memo(function ToolActivityItem({
  msg,
}: {
  msg: ToolItem;
}): React.JSX.Element {
  const [open, setOpen] = useState(false);
  const call = isToolCall(msg);
  const failed = call && msg.status === "failed";
  const hasAttachments =
    !call && !!msg.attachments && msg.attachments.length > 0;

  return (
    <div className="chat-tool-item">
      <button
        type="button"
        className="chat-tool-item-header"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        <ChevronRight
          size={12}
          className={`chat-tool-item-chevron${
            open ? " chat-tool-item-chevron--open" : ""
          }`}
        />
        <ToolGlyph
          toolName={msg.name}
          size={13}
          className={`chat-tool-item-glyph${
            failed ? " chat-tool-item-glyph--failed" : ""
          }`}
        />
        <span className="chat-tool-item-name">
          {humanizeToolName(msg.name)}
        </span>
        <span className="chat-tool-item-detail">{itemDetail(msg)}</span>
      </button>
      <div
        className={`chat-tool-collapse${open ? " chat-tool-collapse--open" : ""}`}
      >
        <div className="chat-tool-collapse-inner">
          <div className="chat-tool-item-body">
            {hasAttachments && (
              <div className="chat-history-attachments">
                {msg.attachments!.map((att: Attachment) => (
                  <AttachmentChip key={att.id} attachment={att} />
                ))}
              </div>
            )}
            <pre
              className={`chat-history-pre ${
                call ? "chat-history-pre--code" : "chat-history-pre--scroll"
              }`}
            >
              {call ? msg.args || "(no arguments)" : msg.content || "(empty)"}
            </pre>
          </div>
        </div>
      </div>
    </div>
  );
});

export const ToolActivityGroup = memo(function ToolActivityGroup({
  items,
  active = false,
  showAvatar = true,
  agent,
}: {
  items: ToolItem[];
  /** True while the turn is still streaming and this is the trailing run —
   *  drives the spinner on the collapsed summary. */
  active?: boolean;
  showAvatar?: boolean;
  /** Appearance of the chatting agent, shown once the avatar goes idle. */
  agent?: AgentAvatarInfo;
}): React.JSX.Element {
  const [open, setOpen] = useState(false);
  const last = items[items.length - 1];
  const detail = itemDetail(last);
  const title = toolActivityGroupTitle(items);
  const soloTool = singleToolName(items);
  const orderedItems = orderToolActivityItems(items);

  return (
    <div
      className={`chat-message chat-message-agent chat-message-history${
        showAvatar ? "" : " chat-message--grouped"
      }`}
    >
      {showAvatar ? (
        <HermesAvatar active={active} agent={agent} />
      ) : (
        <AvatarSpacer />
      )}
      <div
        className={`chat-tool-group${active ? " chat-tool-group--active" : ""}`}
      >
        <button
          type="button"
          className="chat-tool-group-summary"
          aria-expanded={open}
          onClick={() => setOpen((o) => !o)}
        >
          {active ? (
            <OrbLoader
              state="working"
              size={20}
              aria-label="tool-loading"
              className="chat-tool-group-spinner"
            />
          ) : soloTool ? (
            <ToolGlyph
              toolName={soloTool}
              size={13}
              className="chat-tool-group-icon"
            />
          ) : (
            <Wrench size={13} className="chat-tool-group-icon" />
          )}
          <span className="chat-tool-group-name">{title}</span>
          {detail && <span className="chat-tool-group-detail">{detail}</span>}
          <ChevronRight
            size={14}
            className={`chat-tool-group-chevron${
              open ? " chat-tool-group-chevron--open" : ""
            }`}
          />
        </button>
        <div
          className={`chat-tool-collapse${open ? " chat-tool-collapse--open" : ""}`}
        >
          <div className="chat-tool-collapse-inner">
            <div className="chat-tool-group-items">
              {orderedItems.map((it, index) => (
                <ToolActivityItem key={`${it.id}-${index}`} msg={it} />
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
});

import { useCallback, useRef, useState } from "react";

interface UseInputHistoryArgs {
  /** Current draft text — used to save the in-progress draft on first ArrowUp. */
  currentInput: string;
  /** Apply recalled history (or restored draft) text to the textarea. */
  applyText: (text: string) => void;
}

interface UseInputHistoryResult {
  /** Append a freshly-sent message to history; resets the cursor. */
  push: (text: string) => void;
  /** Move backwards through history; returns false if there's nothing to recall. */
  recallPrev: () => boolean;
  /** Move forwards through history; restores the draft past the newest entry. */
  recallNext: () => boolean;
  /** True if the user is currently navigating history (not editing fresh). */
  isNavigating: () => boolean;
  /** Number of entries — used to decide whether ArrowUp should engage. */
  size: () => number;
}

/**
 * Terminal-style command history navigation. State is held in refs so that
 * key presses don't trigger React re-renders for navigation alone — only the
 * applied text change (via `applyText`) re-renders the textarea.
 */
export function useInputHistory({
  currentInput,
  applyText,
}: UseInputHistoryArgs): UseInputHistoryResult {
  const [history, setHistory] = useState<string[]>([]);
  const indexRef = useRef(-1);
  const draftRef = useRef("");

  const push = useCallback((text: string) => {
    setHistory((prev) => [...prev, text]);
    indexRef.current = -1;
    draftRef.current = "";
  }, []);

  const recallPrev = useCallback((): boolean => {
    if (history.length === 0) return false;
    const cur = indexRef.current;
    const next = cur === -1 ? history.length - 1 : Math.max(0, cur - 1);
    if (cur === -1) draftRef.current = currentInput;
    indexRef.current = next;
    applyText(history[next]);
    return true;
  }, [history, currentInput, applyText]);

  const recallNext = useCallback((): boolean => {
    const cur = indexRef.current;
    if (cur === -1) return false;
    if (cur < history.length - 1) {
      indexRef.current = cur + 1;
      applyText(history[cur + 1]);
    } else {
      indexRef.current = -1;
      applyText(draftRef.current);
    }
    return true;
  }, [history, applyText]);

  const isNavigating = useCallback(() => indexRef.current !== -1, []);
  const size = useCallback(() => history.length, [history.length]);

  return { push, recallPrev, recallNext, isNavigating, size };
}

import type { ModelMessage } from 'ai';
import { activatedToolNamesFromResult, activationProviderOptions } from '../tool-activation';
import { compactToolResultForModel } from '../tool-result-compaction';

interface ToolEvent {
  readonly name: string;
  readonly args: unknown;
}

interface ToolExecution {
  readonly success: boolean;
  readonly result: unknown;
}

export function codexToolInput(value: unknown): string {
  try {
    return JSON.stringify(value ?? null);
  } catch {
    return '[unserializable tool input]';
  }
}

function resultForHistory(result: unknown): unknown {
  if (!result || typeof result !== 'object' || Array.isArray(result)) return result;
  const record = result as Record<string, unknown>;
  if (!Array.isArray(record.__images)) return result;
  const { __images, ...rest } = record;
  return { ...rest, __images: `[${__images.length} image payloads omitted]` };
}
function resultForModelHistory(event: ToolEvent, execution: ToolExecution): unknown {
  const result = resultForHistory(execution.result);
  return event.name === 'load_skill' ? result : compactToolResultForModel(result);
}


export function codexToolHistoryEntry(
  event: ToolEvent,
  execution: ToolExecution,
): ModelMessage {
  const text = [
    `[tool call: ${event.name}] ${codexToolInput(event.args)}`,
    `[tool result: ${event.name}; success=${execution.success}] ${codexToolInput(resultForModelHistory(event, execution))}`,
  ].join('\n');
  const providerOptions = event.name === 'ToolSearch'
    ? activationProviderOptions(activatedToolNamesFromResult(execution.result))
    : undefined;
  return providerOptions
    ? { role: 'assistant', content: [{ type: 'text', text, providerOptions }] }
    : { role: 'assistant', content: text };
}

import assert from 'node:assert/strict';
import {
  loadChat,
  resetProjectStoreMemory,
  saveChat,
  saveServerRunChat,
} from '../persist/projectStore.ts';
import { sanitizePortableChat } from '../persist/projectChatTransfer.ts';
import { finishRecoveredRun } from './serverRunRecovery.ts';
import {
  readStoredServerRun,
  saveStoredServerRun,
} from './serverRunSessionStorage.ts';

class MemoryStorage implements Storage {
  private readonly values = new Map<string, string>();
  get length(): number { return this.values.size; }
  clear(): void { this.values.clear(); }
  getItem(key: string): string | null { return this.values.get(key) ?? null; }
  key(index: number): string | null { return [...this.values.keys()][index] ?? null; }
  removeItem(key: string): void { this.values.delete(key); }
  setItem(key: string, value: string): void { this.values.set(key, value); }
}

resetProjectStoreMemory();
const projectId = 'server-run-model-history';
const runId = 'run-model-history';
const nextChat = {
  messages: [
    { role: 'user', text: 'first turn' },
    { role: 'assistant', text: 'first answer' },
  ],
  llm: [
    { role: 'user', content: 'first turn' },
    { role: 'assistant', content: 'first answer' },
  ],
};
assert.equal(await saveServerRunChat(projectId, runId, nextChat), true);
assert.equal(await saveServerRunChat(projectId, runId, {
  ...nextChat,
  llm: [...nextChat.llm, ...nextChat.llm],
}), false, 'the same terminal run cannot append its model turn twice');
await saveChat(projectId, { ...nextChat, messages: [...nextChat.messages, { role: 'system' }] });
const persisted = await loadChat(projectId);
assert.deepEqual(persisted?.llm, nextChat.llm);
assert.deepEqual(persisted?.serverRunTurnIds, [runId],
  'ordinary chat persistence preserves the atomic server-run commit marker');
assert.equal(sanitizePortableChat(persisted!).serverRunTurnIds, undefined,
  'portable chat never exports local server-run idempotency markers');

const originalStorage = Object.getOwnPropertyDescriptor(globalThis, 'localStorage');
Object.defineProperty(globalThis, 'localStorage', {
  configurable: true,
  value: new MemoryStorage(),
});
try {
  const terminalProject = 'server-run-terminal-barrier';
  const terminalRun = 'run-terminal-barrier';
  assert(saveStoredServerRun(terminalProject, {
    projectId: terminalProject,
    runId: terminalRun,
    content: 'persist this model turn',
  }));
  const releaseCommit = Promise.withResolvers<void>();
  const finishing = finishRecoveredRun({
    projectId: terminalProject,
    runId: terminalRun,
    status: 'completed',
    assistantText: 'durable answer',
    onTerminal: async () => 'finalized' as const,
    commitModelTurn: async () => releaseCommit.promise,
  });
  await Promise.resolve();
  assert.equal(readStoredServerRun(terminalProject)?.runId, terminalRun,
    'terminal recovery credentials remain until model history persistence completes');
  releaseCommit.resolve();
  assert.equal(await finishing, 'finalized');
  assert.equal(readStoredServerRun(terminalProject), null,
    'terminal recovery credentials clear only after the model turn is durable');
} finally {
  if (originalStorage) Object.defineProperty(globalThis, 'localStorage', originalStorage);
  else Reflect.deleteProperty(globalThis, 'localStorage');
}

