import { ToolDefinition, ToolResult } from '../core/tool-registry.js';
import { PhotoshopConnection } from '../platform/connection.js';
import { PhotoshopAPIFactory } from '../api/photoshop-api.js';
import { ExtendScriptSnippets } from '../api/extendscript.js';

export function createHistoryTools(connection: PhotoshopConnection): ToolDefinition[] {
  return [
    {
      tool: {
        name: 'photoshop_undo',
        description: 'Undo the last operation(s) - equivalent to Ctrl/Cmd+Z',
        inputSchema: {
          type: 'object',
          properties: {
            steps: {
              type: 'number',
              description: 'Number of steps to undo (default: 1)',
              minimum: 1,
              default: 1,
            },
          },
        },
      },
      handler: async (args) => undo(connection, args),
    },
    {
      tool: {
        name: 'photoshop_redo',
        description: 'Redo the previously undone operation(s) - equivalent to Ctrl/Cmd+Shift+Z',
        inputSchema: {
          type: 'object',
          properties: {
            steps: {
              type: 'number',
              description: 'Number of steps to redo (default: 1)',
              minimum: 1,
              default: 1,
            },
          },
        },
      },
      handler: async (args) => redo(connection, args),
    },
    {
      tool: {
        name: 'photoshop_get_history',
        description: 'Get the history states of the active document',
        inputSchema: {
          type: 'object',
          properties: {},
        },
      },
      handler: async () => getHistory(connection),
    },
  ];
}

async function undo(
  connection: PhotoshopConnection,
  args: Record<string, unknown>
): Promise<ToolResult> {
  const steps = (args.steps as number) || 1;

  try {
    const apiFactory = new PhotoshopAPIFactory(connection);
    const api = await apiFactory.createAPI();

    const script = ExtendScriptSnippets.undo(steps);
    const result = await api.executeScript(script);

    return {
      content: [
        {
          type: 'text' as const,
          text: `Undo successful (${steps} step${steps > 1 ? 's' : ''})\nResult: ${JSON.stringify(result)}`,
        },
      ],
    };
  } catch (error) {
    return {
      content: [
        {
          type: 'text' as const,
          text: `Error undoing: ${error instanceof Error ? error.message : String(error)}`,
        },
      ],
      isError: true,
    };
  }
}

async function redo(
  connection: PhotoshopConnection,
  args: Record<string, unknown>
): Promise<ToolResult> {
  const steps = (args.steps as number) || 1;

  try {
    const apiFactory = new PhotoshopAPIFactory(connection);
    const api = await apiFactory.createAPI();

    const script = ExtendScriptSnippets.redo(steps);
    const result = await api.executeScript(script);

    return {
      content: [
        {
          type: 'text' as const,
          text: `Redo successful (${steps} step${steps > 1 ? 's' : ''})\nResult: ${JSON.stringify(result)}`,
        },
      ],
    };
  } catch (error) {
    return {
      content: [
        {
          type: 'text' as const,
          text: `Error redoing: ${error instanceof Error ? error.message : String(error)}`,
        },
      ],
      isError: true,
    };
  }
}

async function getHistory(connection: PhotoshopConnection): Promise<ToolResult> {
  try {
    const apiFactory = new PhotoshopAPIFactory(connection);
    const api = await apiFactory.createAPI();

    const script = ExtendScriptSnippets.getHistoryStates();
    const result = await api.executeScript(script);

    return {
      content: [
        {
          type: 'text' as const,
          text: `History States:\n${JSON.stringify(result, null, 2)}`,
        },
      ],
    };
  } catch (error) {
    return {
      content: [
        {
          type: 'text' as const,
          text: `Error getting history: ${error instanceof Error ? error.message : String(error)}`,
        },
      ],
      isError: true,
    };
  }
}

import { ToolDefinition, ToolResult } from '../core/tool-registry.js';
import { PhotoshopConnection } from '../platform/connection.js';
import { ExtendScriptSnippets } from '../api/extendscript.js';
import {
  atomicFailureFromError,
  atomicSuccess,
  parseSnippetResult,
  runSnippet,
} from './atomic-shared.js';
import { BATCH_SCRIPT_TIMEOUT_MS } from '../platform/script-timeout.js';

const STACK_MODES = {
  mean: 'stackModeMean',
  median: 'stackModeMedian',
  maximum: 'stackModeMaximum',
  minimum: 'stackModeMinimum',
  summation: 'stackModeSummation',
  stddev: 'stackModeStandardDeviation',
} as const;
type StackMode = keyof typeof STACK_MODES;

export function createStackTools(connection: PhotoshopConnection): ToolDefinition[] {
  return [
    {
      tool: {
        name: 'photoshop_image_stack',
        description:
          'Load 2+ image files into one document, convert to a smart object and apply a stack mode (mean/median/max/min/...). Classic "remove tourists from N shots" or noise reduction — no generative AI involved.\n\n' +
          'Users often say: remove tourists, median stack, average these photos, noise stack, turistleri sil.\n\n' +
          'Use when: the user has multiple aligned shots of the same scene and wants a statistical blend.\n' +
          'Do NOT use when: removing a single object from one photo — use photoshop_generative_remove or photoshop_content_aware_fill.\n\n' +
          'Returns: JSON { ok, summary, details: { file_count, mode, layer_name } }.\n' +
          'Preconditions: 2+ existing image files. Side effects: opens the files; the stacked result becomes the active document.',
        inputSchema: {
          type: 'object',
          properties: {
            files: {
              type: 'array',
              items: { type: 'string' },
              description: 'Absolute paths of the images to stack (min 2)',
              minItems: 2,
            },
            mode: {
              type: 'string',
              enum: Object.keys(STACK_MODES),
              description: 'Stack mode — median removes transient objects, mean reduces noise',
              default: 'median',
            },
          },
          required: ['files'],
        },
      },
      handler: async (args) => imageStack(connection, args),
    },
  ];
}

async function imageStack(
  connection: PhotoshopConnection,
  args: Record<string, unknown>
): Promise<ToolResult> {
  const files = Array.isArray(args.files)
    ? args.files.filter((f): f is string => typeof f === 'string' && f.trim().length > 0)
    : [];
  if (files.length < 2) {
    return atomicFailureFromError(new Error('files must contain at least 2 image paths'));
  }
  const mode: StackMode =
    typeof args.mode === 'string' && args.mode in STACK_MODES ? (args.mode as StackMode) : 'median';

  try {
    const raw = await runSnippet(
      connection,
      ExtendScriptSnippets.imageStackMode(files, STACK_MODES[mode]),
      BATCH_SCRIPT_TIMEOUT_MS
    );
    const parsed = parseSnippetResult(raw);
    if (!parsed) {
      return atomicFailureFromError(new Error(`Unparseable image stack result: ${String(raw)}`));
    }
    if (parsed.ok === false) {
      return atomicFailureFromError(new Error(String(parsed.message || 'Image stack failed')));
    }
    return atomicSuccess(`Image stack applied (${mode}, ${files.length} files)`, {
      mode,
      file_count: files.length,
      layer_name: parsed.layer_name,
    });
  } catch (error) {
    return atomicFailureFromError(error);
  }
}
